#!/usr/bin/env python3
from pathlib import Path
import base64
import lzma
import subprocess
import sys

root = Path(sys.argv[1] if len(sys.argv) > 1 else "game")
if not (root / "project.godot").is_file():
    raise SystemExit(f"Project root not found: {root}")

PATCH_B64 = ""

patch_bytes = lzma.decompress(base64.b64decode(PATCH_B64))
patch_path = root / ".v0173.patch"
patch_path.write_bytes(patch_bytes)
try:
    subprocess.run(["patch", "-p1", "-i", str(patch_path)], cwd=root, check=True)
finally:
    patch_path.unlink(missing_ok=True)


def replace_exact(rel: str, old: str, new: str) -> None:
    path = root / rel
    text = path.read_text(encoding="utf-8")
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{rel}: expected 1 occurrence, found {count}: {old!r}")
    path.write_text(text.replace(old, new), encoding="utf-8")

replace_exact("scripts/save/save_manager.gd", 'const GAME_VERSION := "0.17.2"', 'const GAME_VERSION := "0.17.3"')
replace_exact("export_presets.cfg", 'export_path="build/android/Wanderfall-v0.17.2-debug.apk"', 'export_path="build/android/Wanderfall-v0.17.3-debug.apk"')
replace_exact("export_presets.cfg", 'version/code=19', 'version/code=20')
replace_exact("export_presets.cfg", 'version/name="0.17.2"', 'version/name="0.17.3"')

print("Applied Wanderfall v0.17.3 touch layout fixes: visible resize grips, reliable quickbar, and per-control layout editor.")
